<div class="admin-page-head"><div><h1>آمار بازدید سایت</h1><p>نمایش‌های ثبت‌شده در <?= (int)$days ?> روز گذشته</p></div><?= CHtml::beginForm('','get') ?><?= CHtml::dropDownList('days',$days,array(7=>'۷ روز',30=>'۳۰ روز',90=>'۹۰ روز')) ?><?= CHtml::submitButton('نمایش',array('class'=>'btn btn-outline')) ?><?= CHtml::endForm() ?></div>
