<?php foreach(array('صفحات پربازدید'=>array($pages,'path'),'منابع ورود'=>array($sources,'referrer_host'),'نوع دستگاه'=>array($devices,'device')) as $title=>$data): ?><section class="panel"><h2><?= $title ?></h2><table class="data-table"><thead><tr><th>عنوان</th><th>بازدید</th></tr></thead><tbody><?php foreach($data[0] as $row): ?><tr><td><?= CHtml::encode($row[$data[1]]?:'ورود مستقیم') ?></td><td><?= number_format($row['views']) ?></td></tr><?php endforeach; ?></tbody></table></section><?php endforeach; ?>
